To simplify the computation, we divide the training process into $K$ \emph{phases}, where $K$ is a design variable. Each phase $s\in \{1,\dots K\}$ contains $\tau_s$ consecutive iterations of using the random mixing matrix $\bm{W}_s$. 
For clarity, we 
use $\bm{W}_s^{(t)}$ to refer to the mixing matrix used in the $t$-th iteration of phase $s$, which is an instance of $\bm{W}_s$ drawn independently in each iteration.
This changes our design problem into the following optimization: 
\begin{subequations}\label{eq:adaptive mixing matrix design, phased}
\begin{align}
&    \min_{K, \{\bm{W_{s}}, \tau_s\}_{s=1}^K }\:  
    \E\left[
    \max_{i\in V} \sum_{s=1}^K 
    \sum_{t=1}^{\tau_s}
    c_i(\bm{W}_{s}^{(t)}) 
    \right] \label{eq:obj over K phases} \\
\mbox{s.t. }
& \tau_1 + \dots + \tau_K = T_2(\bm{p}, \epsilon, \overline{\bm{x}}^{(0)}) \label{eq: nonconvex constraint over K phases} \\
% & p^{(\sum_{l=1}^{{s-1}}\tau_{l}+1)} = \dots = p^{(\sum_{l=1}^{{s}} \tau_{l})} = 1-\rho(\bm{W}_s),\label{eq: phase requirement}\\
% &\hspace{13em}\forall s=1,\ldots,K.\nonumber \\
& p^{(t)} =  1-\rho(\bm{W}_s),\: \forall~ t=\big(\sum_{l=1}^{{s-1}}\tau_{l},\ldots,\sum_{l=1}^{{s}} \tau_{l} \big], \label{eq: phase requirement}\\
& \hspace{13em} \forall s=1,\ldots,K.\nonumber
\end{align}
\end{subequations}
The decision variables are: the number of phases $K$, the $K$ random mixing matrices $\{\bm{W}_s\}_{s=1}^K$, and the number of iterations $\{\tau_s\}_{s=1}^K$ for using each. 
For a given solution to \eqref{eq:adaptive mixing matrix design, phased}, 
the number of iterations required for convergence is denoted as \looseness=-1
\begin{align}
T_3((p_1, \tau_1), (p_2, \tau_2), \dots, p_K) :=  T_2(\bm{p}, \epsilon, {\bm{x}}^{(0)}),
\end{align}
where $p_s:=1-\rho(\bm{W}_s)$ is the convergence parameter for each phase $s=1,\dots, K$. 
Note that, given $(p_1, \tau_1), (p_2, \tau_2)  \dots, p_K$ and $K$,  $\tau_K$ is no longer an independent variable due to \eqref{eq: nonconvex constraint over K phases}. 

\subsection{A Related Sub-problem}

Since $T_3((p_1, \tau_1), \dots, p_K)$ is a {decreasing} function of each $p_s=1-\rho(\bm{W}_s)$, we want to design a random mixing matrix for each phase $s$ to minimize $\rho(\bm{W}_s)$ without triggering too many communications. To this end, we introduce a sub-problem of budgeted mixing matrix design.  
Let $D>0$ denote the \emph{budget} for the per-iteration expected energy consumption at each node in a given phase. We formulate the per-phase mixing matrix design problem  (omitting the phase index) as 
\begin{subequations}\label{eq:budgeted random W design}
\begin{align}
    & \min_{\Pr[\cdot]} \left\| \sum_{\bm{W}\in \mathcal{M}} \Pr[\bm{W}] \bm{W}^\top \bm{W} - J \right\| \label{eq: broadcast K=1 obj} \\
    & \sum_{\bm{W} \in \mathcal{M}} \Pr[\bm{W}] = 1, \text{ and } \Pr[\bm{W}] \ge 0 ~~ \forall~ \bm{W} \in \mathcal{M},  \\
    & \sum_{\bm{W} \in \mathcal{M}} \Pr[\bm{W}] c_i(\bm{W})  \le D, \forall~ i\in V \label{eq: exp edge constraint}\\
    &  \mathbbm{1}[\Pr[\bm{W}]\cdot \bm{W}[i,j] \neq 0] \le \mathbbm{1}[E[i,j]\neq 0], \label{eq:ramdomized graph constraint} \\
    &\hspace{13em} \forall~ \bm{W}\in \mathcal{M}, \forall~ i\neq j \in V, \nonumber
\end{align}
\end{subequations}
where we use $\mathcal{M}$ to denote the set of symmetric matrices whose row/column sums are $1$, and $\Pr[\bm{W}]$ to denote the probability of choosing $\bm{W}\in \mathcal{M}$ in each iteration of this phase.\looseness=-1 %as the mixing matrix. 
 % \Xusheng{It is unclear whether this problem (or its approximation variants) falls under NP-hard class or P class. I feel you can have a FPTAS}

% In \cite{Herrera25OJCS}, a related optimization problem has been discussed and concluded to be not convex. 
We will dive into a concrete solution to \eqref{eq:budgeted random W design} in Section~\ref{sec:Lower-level optimization for broadcast communication}-\ref{sec:Lower-level optimization under unicast communication}. To present the overall solution, we assume the existence of a hypothetical solution $\mathcal{A}$ to \eqref{eq:budgeted random W design}, treated as a black box for the time being, with the following property: for any budget $D$, $\mathcal{A}$ provides a random mixing matrix $\bm{W}$ that is feasible for \eqref{eq:budgeted random W design} with the guarantee that there exists a function $\rho_{\mathcal{A}}^+:\mathds{R}^+\rightarrow\mathds{R}^+ \cup \{\infty\}$ such that $\rho(\bm{W})\le \rho^+_{\mathcal{A}}(D)$. 


Under a given budget $D$, one can bound the expected maximum energy consumption per node for a phase of $T$ iterations by the following lemma. 
\begin{lemma}\label{lem:bound under budget D for K=1}
Let $D>0$ and $T>0$. Suppose a random mixing matrix $\bm{W}$ satisfies  $\E[c_i(\bm{W})] \le D$ ($\forall i\in V$).
If $\bm{W}^{(1)}, \dots, \bm{W}^{(T)}$ are i.i.d. copies of $\bm{W}$, 
then 
\begin{equation}\label{eq:exp maximum bound}
    \E\left[  \max_i \sum_{t=1}^T c_i(\bm{W}^{(t)}) \right] \le D\cdot \left(T
    + m\sqrt{\frac{T \pi}{8}} \right) 
    =: q(T,D). 
\end{equation}
\end{lemma}
The proof of Lemma~\ref{lem:bound under budget D for K=1} is deferred to Section~\ref{sec: deferred proof}.

\subsection{Case Studies for $K=1$ and $K=2$}

\subsubsection{Computation of $T_3$}
Next we illustrate computation for $T_3$ through case studies of $K=1$ and $K=2$.

In the case of $K=1$, as explained in the first remark below Theorem~\ref{thm: new convergence bound nonconvex}, we have $\Pi_1(T)\equiv 2/p_1$ and $\Pi_2(T)\equiv 2/p_1^2$.
With this simplification,
\begin{align}
T_3(p_1)&= T_1(2/p_1, 2/p_1^2, 2/p_1, p_1, \epsilon,  \overline{\bm{x}}^{(0)}) \nonumber\\
&= O\left(  \frac{f_0 L\sqrt{(1+M_1) (1+M_2)}}{\epsilon p_1}\right) \nonumber\\
&    +O\left(\frac{f_0 L^2 [\Xi_0 + p_1(1+M_1)]}{\epsilon p_1} 
    \right) \nonumber\\
&     +f_0 L \cdot O\left(
    {\hat{\sigma}^2\over m\epsilon^2} +{\sqrt{(M_1 \hat{\zeta}^2+\hat{\sigma}^2) p_1 + \hat{\zeta}^2  } \over  \epsilon^{3/2}p_1}
    \right).
\end{align}
In the case of $K=2$, $\Pi_1(T)$ and $\Pi_2(T)$ are given by the following lemma.
\begin{lemma}\label{lem:T((p1,tau1),p2)}
Let $T\ge \tau_1$ be a fixed integer.
If $p^{(1)}=\cdots=p^{(\tau_1)}=p_1$ and $p^{(\tau_1+1)}=\cdots=p^{(T)}=p_2$, then $\Pi_1(T)$ and $\Pi_2(T)$ as defined in \eqref{eq:Pi_1} satisfy the followings:
\begin{align*}
    \Pi_1(T) &= \frac{2(T-\tau_1)}{T p_2} + \frac{2\tau_1}{T p_1} -  (\frac{2}{T p_1} - \frac{2}{Tp_2}) \sum_{j=1}^{\tau_1} (1-\frac{p_1}{2})^{j}, \\ 
    \Pi_2(T)  &= \frac{2(T-\tau_1)}{T p_2^2} + \frac{2\tau_1}{T p_1^2} -  (\frac{2}{T p_1^2} - \frac{2}{Tp_2 p_1}) \sum_{j=1}^{\tau_1} (1-\frac{p_1}{2})^{j}.
\end{align*}
\end{lemma}
The proof of Lemma~\ref{lem:T((p1,tau1),p2)} is elementary and will be provided in Appendix~\ref{sec: deferred proof}.
From Lemma~\ref{lem:T((p1,tau1),p2)} we have $\Pi_1(T)\rightarrow 2/p_2$ and $\Pi_2(T) \rightarrow 2/p_2^2$ as $T$ grows. 
Therefore, by a linear search over $T=\tau_1, \tau_1 +1, \dots$, the first $T$ satisfying $T\ge T_1(\Pi_1(T), \Pi_2(T), \pi_0, p_{\min}, \epsilon, \overline{\bm{x}}^{(0)})$ is the value of $T_3((p_1, \tau_1), p_2)$. \looseness=-1


\subsubsection{Computation of Design Objective}%{Introduction to a budgeted problem}


Lemma~\ref{lem:bound under budget D for K=1} 
together with the function $\rho^+_{\mathcal{A}}(D)$ enables us to upper-bound the objective function \eqref{eq:obj over K phases}.
As an example, consider $K=1$.  
By Lemma~\ref{lem:bound under budget D for K=1}, the random mixing matrix $\bm{W}$ designed by $\mathcal{A}$ for budget $D$ will achieve convergence with an expected maximum energy consumption per node no more than  
\begin{equation}
\label{eq: QK=1}
Q_{K=1}(D) := 
q\big(T_3(1-\rho_{\mathcal{A}}^+(D)), D\big).
\end{equation}
Thus, by relaxing the objective function \eqref{eq:obj over K phases} into its upper bound \eqref{eq: QK=1},  we can obtain a 1-phase (randomized) mixing matrix design by minimizing $Q_{K=1}(D)$ over $D \in \mathds{R}^+$ and then feeding the resulting $D$ into the given subroutine $\mathcal{A}$ to obtain a random mixing matrix $\bm{W}$. 

\begin{algorithm}[tb]
\small
\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
% \SetKwFor{RepTimes}{repeat}{times}{end}
\Input{Maximum \#phases $\overline{K}$, subroutine $\mathcal{A}$ for the problem \eqref{eq:budgeted random W design} and an associated function $\rho^+_{\mathcal{A}}$.}
\Output{Mixing matrices $\bigcup_{s=1}^{K^*}\{\bm{W}_s^{(t)}\}_{t=1}^{\tau^*_s}$.}
\For{$K \gets 1$ \KwTo $\overline{K}$}{
Minimize $Q_K=\sum_{s=1}^{K} q(\tau_s, D_s)$ for $\tau_K = T_3((p_1,\tau_1), \dots, (p_{K-1}, \tau_{K-1}), p_K) - \sum_{s=1}^{K-1} \tau_s$ and $p_s=1-\rho^+_{\mathcal{A}}(D_s)$\; \label{MMMD:2}
}
$K^* \gets \argmin_K Q_K$, with the corresponding solution $D^*_1, \dots, D^*_{K^*}, \tau^*_1, \dots, \tau^*_{K^*-1}$\;
\For{$s \gets 1$ \KwTo $K^*$}{
    \For{$t \gets 1$ \KwTo $\tau^*_s$}{
           $\bm{W}_s^{(t)} \gets \mathcal{A}(D^*_s)$\;
    }
}
return $\bigcup_{s=1}^{K^*}\{\bm{W}_s^{(t)}\}_{t=1}^{\tau^*_s}$\;
\caption{Multi-phase Mixing Matrix Design}
\label{alg:framework}
\vspace{-.05em}
\end{algorithm}

Now consider the case of $K=2$. 
This enlarges our design space to include distinct positive budgets $D_1>0$ and $D_2>0$ for each phase, as well as the number of iterations $\tau_1$ for phase $1$. 
We first rewrite the objective function \eqref{eq:obj over K phases} specific to $K=2$:
\begin{align}
&\min_{ \{\bm{W_{s}}, \tau_s\}_{s=1}^K }\:  
    \E\left[
    \max_{i\in V} \sum_{s=1}^K 
    \sum_{t=1}^{\tau_s}
    c_i(\bm{W}_{s}^{(t)}) 
    \right] =
    \nonumber\\
& \min_{ \bm{W}_1, \bm{W}_2, \tau_1}\hspace{-.5em} \E\left[ 
    \max_{i\in V} \big[ \sum_{t=1}^{\tau_1}c_i(\bm{W}_1^{(t)}) + \hspace{-.5em} \sum_{t=\tau_1+1}^{T_3( (p_1, \tau_1), p_2)}\hspace{-.5em} c_i(\bm{W}_2^{(t-\tau_1)}) \big]
\right] \label{eq:K=2 simplified objective randomized}
\end{align}
%As part of the design process, we can allocate 
Given a solution $\mathcal{A}$ to the sub-problem \eqref{eq:budgeted random W design}, we apply $\mathcal{A}$ to $D_1$ and $D_2$, respectively. 
Then, based on the performance bound $\rho^+_{\mathcal{A}}$, the objective \eqref{eq:K=2 simplified objective randomized} of 2-phase design can be upper-bounded by
\begin{equation}
    \label{eq:Q K=2}
   Q_{K=2}(D_1, D_2, \tau_1) := 
   q(\tau_1, D_1) + q(T_3((p_1, \tau_1), p_2) - \tau_1, D_2), 
   % [\tau_1 (D_1 - D_2) + T_2((p_1, \tau_1), p_2) \cdot D_2] \cdot (1+o(1)).
\end{equation}
where $p_1 = 1- \rho^+_{\mathcal{A}}(D_1)$ and $p_2 = 1- \rho_{\mathcal{A}}^+(D_2)$. 
Therefore, optimizing $Q_{K=2}(D_1, D_2, \tau_1)$ over the $3$-tuple $(D_1, D_2, \tau_1)$ will yield an optimized 2-phase design. % with at most one adaption.

\subsection{Overall Solution}

We propose to solve the multi-phase design problem~\eqref{eq:adaptive mixing matrix design, phased} through a trilevel optimization as shown in Algorithm~\ref{alg:framework}:
\begin{itemize}
    \item \noindent \textbf{Upper-level optimization:}~Decide the number of phases $K$ to minimize the overall objective.

    \item \noindent \textbf{Intermediate-level optimization:}~Given a number of phases $K$, minimize the relaxed objective $Q_K:=\sum_{s=1}^{K} q(\tau_s, D_s)$ to determine the budget $D_s$ and the duration $\tau_s$ of each phase $s=1,\dots, K$.

    \item \noindent \textbf{Lower-level optimization:}~Given the budget $D_s$ of each phase, design a random instance $\bm{W}_s^{(t)}$ of the mixing matrix for each iteration in this phase by applying the given solution to the sub-problem \eqref{eq:budgeted random W design}.
\end{itemize}
The focus of Algorithm~\ref{alg:framework} is on the intermediate-level optimization, which optimizes a function of $2K-1$ variables (i.e., $D_1, \dots, D_K, \tau_1, \dots, \tau_{K-1}$). Given the performance bound $\rho_{\mathcal{A}}^+$ of the lower-level optimization, this intermediate-level optimization only has an $O(K)$-dimensional solution space, which is much more tractable than directly optimizing $K$ $m\times m$ random matrices.  
%remains tractable even when the number of nodes $m$ is large.

\textbf{Remark:} In the remainder of this work, we will solve the upper/intermediate-level optimizations numerically for small values of $K$ to focus on solving the lower-level optimization under broadcast communications. %Although the main contribution of this paper lies in modeling broadcast communication, 
Our trilevel optimization framework is generally applicable under any communication model. %  can also accommodate the unicast cost model.
We leave the development of more efficient solutions to the upper/intermediate-level optimizations to future work.  



\section{Lower-level optimization under broadcast communication}\label{sec:Lower-level optimization for broadcast communication}

In this section, we focus on developing efficient solutions to the budgeted problem defined in \eqref{eq:budgeted random W design} under the broadcast communication cost model.

\subsection{Algorithm Design}

\begin{algorithm}[t]
\caption{Budgeted Mixing Matrix Design for Broadcast Communication}
\label{alg:randomized-W for broadcast}
% \DontPrintSemicolon  % Some stylistic settings (optional)
\small
\KwIn{A base topology $G=(V,E)$ with per-computation  cost $c_i^a$ and per-transmission cost $c_i^b$ ($\forall i\in V$) and per-node  budget $D$. }
\KwOut{A mixing matrix \(\bm{W}\) with an expected per-node cost no more than $D$.}

\BlankLine
\textbf{Step 1: Sample a subset of nodes to activate} \\
\Indp
Let $U \gets \emptyset$ denote the set of activated nodes\;
\ForEach{\(i \in V\)}{
    Add node \(i\) to \(U\) independently with probability
    $\min((D-c_i^a)/c_i^b,1)$\;
}
\Indm

\BlankLine
\textbf{Step 2: Design entries for nodes not in \(U\)} \\
\Indp
\ForEach{\(i \in V \setminus U\)}{
   \(\bm{W}[i,i] \gets 1\)\;
   \(\bm{W}[i,j]\gets 0,\: \bm{W}[j,i] \gets 0\) for all \( j \neq i\)\;
}
\Indm

\BlankLine
\textbf{Step 3: Design entries for nodes in \(U\)} \\
\Indp
\ForEach{\(i \in U\)}{
    \ForEach{$j\in U \setminus V_i$}
    {
        $\bm{W}[i,j] \gets 0$\; 
    }

    \ForEach{$j\in (V_i \cap U)\setminus \{i\}$}
    {\(\bm{W}[i,j] \gets 1 / \max(|V_i\cap U|, |V_j\cap U|)\)\;}

    \(\bm{W}[i,i] \gets 1-\sum_{j\in V\setminus \{i\}}\bm{W}[i,j] \)\;
}
\end{algorithm}


To pose a well-defined and non-trivial problem, we  assume
\begin{align}\label{eq:condition on D - clique}
\max_i c_i^a \le D < \max_i (c_i^a + c_i^b). 
\end{align}
Indeed, if $D\ge \max_i (c_i^a + c_i^b)$, then we can deterministically activate all the nodes, in which case the optimal mixing matrix can be efficiently computed by solving a semi-definite programming problem~\cite{Chiu23JSAC}. 
Meanwhile, $D< \max_i c_i^a$ is not feasible under the cost model in \eqref{eq:cost definition - broadcast} as some node will exceed the budget even if it does not communicate. % incur unaffordable computation  cost of $c^a_i$ according to \eqref{eq:cost definition - broadcast}. 
% Hence, it suffices to solve \eqref{eq:budgeted random W design - clique} for $c^a \le D <c^a + c^b$. 

Under the cost model \eqref{eq:cost definition - broadcast}, the problem \eqref{eq:budgeted random W design} becomes 
\begin{subequations}\label{eq:budgeted random W design - clique}
